let embeddedRule0266: RuleEntry = RuleEntry(
    id: "phb_ch12_npcs",
    book: "PHB",
    chapterNumber: 12,
    chapterTitle: "NPCs and Followers",
    breadcrumbs: "Player's Handbook > Chapter 12: NPCs and Followers > NPCs",
    topic: "NPCs",
    ruleType: "core_rule",
    summary: "Player characters cannot fight, survive, wheel, deal, plot, or scheme without interacting with nonplayer characters (NPCs). Indeed, the very heart of the AD&D game is the relationship between player characters and nonplayer characters.",
    content: "Player characters cannot fight, survive, wheel, deal, plot, or scheme without interacting with nonplayer characters (NPCs). Indeed, the very heart of the AD&D game is the relationship between player characters and nonplayer characters. How the player characters react to and treat NPCs determines the type of game the group plays. Although many choices are possible, players quickly find that consideration and good treatment of NPCs is the most frequently successful route.\n\n*An NPC is any person, creature, or monster that is controlled by the DM.* Most NPCs are either people (intelligent races that live in local society) or monsters (intelligent and unintelligent creatures that aren't normally found in towns and villages). The term \"monster\" is only a convenient label. It doesn't mean the creature is automatically dangerous or hostile. Likewise, NPCs who are people aren't uniformly helpful and cooperative. As with all things, the range of possible reactions of NPCs to PCs covers the entire spectrum.\n\nIn the course of their adventures, player characters will be most concerned with three groups of NPCs: hirelings, followers, and henchmen. It is their aid that helps player characters vanquish deadly monsters and accomplish mighty deeds. As their names imply, these NPCs can be persuaded in various ways to join the player characters in their adventures. The most common methods of persuasion are money and loyalty.",
    tables: [],
    relatedRuleIds: [],
    relatedSpells: [],
    relatedMagicItems: [],
    searchKeywords: ["npcs"]
)

let embeddedRule0267: RuleEntry = RuleEntry(
    id: "phb_ch12_player_character_obligations",
    book: "PHB",
    chapterNumber: 12,
    chapterTitle: "NPCs and Followers",
    breadcrumbs: "Player's Handbook > Chapter 12: NPCs and Followers > Player Character Obligations",
    topic: "Player Character Obligations",
    ruleType: "core_rule",
    summary: "Whenever a player character takes on a hireling, follower, or henchman, he has committed himself to certain obligations and customs that surround such agreements.",
    content: "Whenever a player character takes on a hireling, follower, or henchman, he has committed himself to certain obligations and customs that surround such agreements. Some of these are obvious, having been worked out between the player character and the NPC in advance. Usually the wage and term of service are settled upon before any agreement is reached. For hirelings and followers, this is a set amount of money each day, week, or month, or a fee for a specific task. Henchmen commonly receive a portion (half a normal share) of all treasure and magic found on adventures. A player character is normally expected to contribute a little more from his own funds, however.\n\nOther obligations of the player character are varied. Some must always be considered, while others almost never come into effect. A player character is expected to provide meals and boarding (unless the NPC has a home nearby). This is the most common obligation and applies to NPCs of all walks of life. For those engaged in more dangerous pursuits, however, additional concessions must be granted. Since horses are expensive, player characters should be ready to cover the cost of mounts lost in combat or on campaign. It is unreasonable to expect a mercenary to buy a new mount from his meager savings. Likewise, other items of war craft—weapons and armor—must be replaced by the player character. All soldiers are expected to provide their own equipment when they are first employed, but the player character must replace all losses. Certainly all player characters are expected to pay the cost of special transport—securing passage on ships and arranging wagons for baggage. Of the grimmer duties, player characters are expected to pay for a decent (though hardly lavish) interment.\n\nOne of the more unusual obligations of a player character is to ransom his men. This is especially true of men lost during a campaign. The greater number of soldiers lost in a battle are not slain but captured. Common practice of the medieval period was to officially ransom these prisoners for well-established prices. A common yeoman footman might ransom for 2 gp, a minor priest for 80 gp, a knight's squire for 200 gp, and a king's man for 500 gp. These are paid for by the lord of the prisoner. A player character (as a lord and master) is expected to do the same. Of course, the player character can pass much of this cost on to his own subjects and the relatives of the prisoner. Thus men might languish for long periods in the hands of the enemy before their ransom was raised. Furthermore, should a player character ransom a hireling, follower, or henchman, he has every reason to expect loyal service from that man in the future. After all, he has demonstrated his willingness to save that NPC from hardship and death.\n\nIn a fantasy world, a player character is also expected to bear the cost of magical spells cast to the benefit of his men. He may arrange to have his men blessed before battle or healed after it. He shouldn't grumble about the expense, because the spells also make good tactical sense. The bless spell increases the success of his army in the field. Magical cures get his army back on its feet quicker. All these things can make him very successful while also making him popular with his hired men.\n\nFinally, the player character is expected to make an effort to raise or restore slain henchmen. This is not a normal expectation of hirelings or followers (although it can happen in extreme cases). The effort should be honest and true. A player character shouldn't fool himself into thinking no one will notice if he doesn't do his utmost. The player character who returns from an adventure minus his henchman is automatically under a cloud of suspicion, despite his most vehement protests. A player character must take great care to maintain his reputation as a good and upright employer.\n\n(See also NPCs in the Monstrous Manual)",
    tables: [],
    relatedRuleIds: [],
    relatedSpells: [],
    relatedMagicItems: [],
    searchKeywords: ["armor", "character", "obligations", "player", "player character obligations", "weapons"]
)

let embeddedRule0268: RuleEntry = RuleEntry(
    id: "phb_ch13_vision_and_light",
    book: "PHB",
    chapterNumber: 13,
    chapterTitle: "Vision and Light",
    breadcrumbs: "Player's Handbook > Chapter 13: Vision and Light > Vision and Light",
    topic: "Vision and Light",
    ruleType: "optional_rule",
    summary: "Before a character can do anything in the dungeon or the wilderness, he has to be able to see what he is doing. If a character can't see a target, his chances of hitting it are very small.",
    content: "Before a character can do anything in the dungeon or the wilderness, he has to be able to see what he is doing. If a character can't see a target, his chances of hitting it are very small. If he can't see, he can't read a scroll or a large \"Keep Out\" sign on the wall. In the AD&D game, characters can see set distances and often by fantastic means that defy logic.\n\n## Limits of Vision\nThe first limitation on vision is how far away an object can be before it cannot be seen clearly. Size and weather have a great effect on this. Mountains can be seen from great distances, 60 to 100 miles or more, yet virtually no detail can be seen. On level ground, the horizon is about five to 12 miles away, but a character usually cannot see a specific object that far away. The limit of vision for seeing and identifying man-sized objects is much less than this.\n\nUnder optimum conditions, the maximum range at which a man-sized object can be seen is about 1,500 yards, if it is moving. If the object doesn't move, it usually cannot be seen at this distance. Even if it is moving, all that can be seen is a moving object. The character cannot tell what it is or what it is doing.\n\nAt 1,000 yards, both moving and stationary man-sized objects can be spotted. General size and shape can be determined, but exact identifications are impossible. It is not likely that creature type can be identified at this range, unless the creature has a very unique shape.\n\nAt 500 yards, general identifications can be made. Size, shape, color, and creature type are all distinguishable. Individuals still cannot be identified, unless they are distinctively dressed or separated from the rest of the group. Livery and heraldic symbols or banners can be seen if large and bold. Most coats of arms cannot be distinguished at this distance. General actions can be ascertained with confidence.\n\nAt 100 yards, individuals can be identified (unless, of course, their features are concealed). Coats of arms are clear. Most actions are easily seen, although small events are unclear.\n\nAt 10 yards, all details but the smallest are clear. Emotions and actions are easily seen, including such small actions as pick-pocketing (if it is detectable).\n\nOf course, conditions are seldom perfect. There are a number of factors that can reduce visibility and alter the ranges at which things can be spotted and identified. Table 62 lists the effects of different types of conditions.\n\nAll ranges are given in yards.\n\n\"Movement\" indicates the maximum distance at which a moving figure can be seen. \"Spotted\" is the maximum distance a moving or a stationary figure can be seen. \"Type\" gives the maximum distance at which the general details of a figure can be seen—species or race, weapons, etc. \"ID\" range enables exact (or reasonably exact) identification. \"Detail\" range means small actions can be seen clearly.\n\nThere are many factors other than weather that affect viewing. Size is an important factor. When looking at a small creature (size S), all categories are reduced to the next lower category (except the \"detail\" range, which remains unchanged). Thus, under clear conditions, the ranges for seeing a small creature are \"movement\" at 1,000 yards, \"spotted\" at 500 yards, \"type\" at 100 yards, and \"ID\" and \"detail\" at 10 yards.\n\nWhen sighting large creatures, the \"movement,\" \"spotting,\" and \"type\" ranges are doubled. Exceptionally large creatures can be seen from even greater distances. Large groups of moving creatures can be seen at great distances. Thus, it is easy to see a herd of buffalo or an army on the march.\n\nThe ranges given in Table 62 do not take terrain into account. All ranges are based on flat, open ground. Hills, mountains, tall grass, and dense woods all drastically reduce the chances of seeing a creature. (The terrain does not alter sighting ranges, only the chances of seeing a creature.) Thus, even though on a clear day woods may hide a bear until he is 30 yards away, it is still a clear day for visibility. The bear, once seen, can be quickly and easily identified as a bear. The DM has more information on specific terrain effects on sighting.\n\nAs a final caveat, the ranges in Table 62 assume Earthlike conditions. Sighting conditions on one of the Lower Planes, or the horizon distance on another world, could be entirely different. If your DM feels he must take this into account, he will have to learn more about this subject at his local library or make it up.\n\n[TABLE_REF: Table 62: Visibility Ranges]\n\n## Light\nMost characters cannot see much without light. Some night conditions (those for the outdoors) are given in Table 62. But all of these assume some small amount of light. In totally lightless conditions, normal vision is impossible, unless a source of light is carried by the party.\n\nLight sources vary in the area they affect. Table 63 gives the radius of light and burning time for the most common types of light sources.\n\nOf course, while a lantern or fire enables characters to see, it does have some disadvantages. The greatest of these is that it is hard to sneak up on someone if he can see you coming. It is hard to remain inconspicuous when you have the only campfire on the plain, or you are carrying the only torch in the dungeon. Furthermore, not only do creatures know you are coming, they can generally see you before you see them (since the light source illuminates the area around you, those outside this area can see into the area). Characters should always bear these risks in mind.\n\n[TABLE_REF: Table 63: Light Sources]\n\n: * Light from these is not cast in a radius, but rather in a cone-shaped beam. At its far end, the cone of light from a beacon lantern is 90 feet wide. A bullseye lantern has a beam 20 feet wide at its far end.\n: ** Magical weapons shed light if your DM allows this optional rule.\n\n## Infravision\nSome characters and monsters have the power of infravision. This can mean one of two things, depending on whether the standard or the optional rule is used (this is discussed in detail in the \nDungeon Master Guide). The choice is left to the DM and he must tell the players how he wants infravision to work. Regardless of how the power functions, the range of infravision is at most 60 feet unless otherwise noted.\n\n## Using Mirrors\nAt times it is useful for characters to look at objects or creatures via reflections in a mirror. This is particularly true of those creatures so hideous (such as a medusa) that gazing directly upon them might turn the viewer to stone. When using a mirror, a light source must be present. Second, attempting to direct your actions by looking in a mirror is very disorienting (try it and see). Thus, all actions requiring an ability or proficiency check or an attack roll suffer a -2 penalty. The character also loses all Dexterity bonuses to Armor Class if fighting an opponent seen only in a mirror.",
    tables: [
        RuleTable(
                tableNumber: "Table 62",
                title: "Table 62: Visibility Ranges",
                headers: ["Condition", "Movement", "Spotted", "Type", "ID", "Detail"],
                rows: [
                    ["Clear sky", "1,500", "1,000", "500", "100", "10"],
                    ["Fog, dense or blizzard", "10", "10", "5", "5", "3"],
                    ["Fog, light or snow", "500", "200", "100", "30", "10"],
                    ["Fog, moderate", "100", "50", "25", "15", "10"],
                    ["Mist or light rain", "1,000", "500", "250", "30", "10"],
                    ["Night, full moon", "100", "50", "30", "10", "5"],
                    ["Night, no moon", "50", "20", "10", "5", "3"],
                    ["Twilight", "500", "300", "150", "30", "10"]
                ]
            ),
        RuleTable(
                tableNumber: "Table 63",
                title: "Table 63: Light Sources",
                headers: ["Source", "Radius", "Burning time"],
                rows: [
                    ["Beacon lantern", "240&nbsp;ft.*", "30 hrs./pint"],
                    ["Bonfire", "50&nbsp;ft.", "1/2 hr./armload"],
                    ["Bullseye lantern", "60&nbsp;ft.*", "2 hrs./pint"],
                    ["Campfire", "35&nbsp;ft.", "1 hr./armload"],
                    ["Candle", "5&nbsp;ft.", "10 min./inch"],
                    ["Continual light", "60&nbsp;ft.", "Indefinite"],
                    ["Hooded lantern", "30&nbsp;ft.", "2 hrs./pint"],
                    ["Light", "20&nbsp;ft.", "Variable"],
                    ["Torch", "15&nbsp;ft.", "30 min."],
                    ["Weapon**", "5&nbsp;ft.", "As desired"]
                ]
            )
    ],
    relatedRuleIds: [],
    relatedSpells: [],
    relatedMagicItems: [],
    searchKeywords: ["armor", "armor class", "dexterity", "light", "movement", "proficiency", "vision", "vision and light", "weapons"]
